using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser("Enter a research topic: ");

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchAsync),
    AIFunctionFactory.Create(webSearch.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client with automatic function-calling
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. Your job is to research the given topic thoroughly
    and produce a clear, well-structured summary.

    You have the following tools:
    • **SearchWeb**  – search the web for a query and get back a list of results
                       (titles, snippets, URLs).
    • **FetchPage**  – fetch the text content of a specific URL for deeper reading.
    • **AddNote**    – save an important finding or quote to your notebook.
    • **GetNotes**   – retrieve everything you have saved so far.

    Workflow:
    1. Search for the topic (try 2-3 varied queries).
    2. Fetch the most promising pages to gather details.
    3. Save key facts, data points, and quotes using AddNote.
    4. After gathering enough information, call GetNotes to review your notes.
    5. Produce a final **Summary** with sections, bullet points, and source URLs.

    Be concise but thorough. Cite sources where possible.
    """;

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research this topic: {topic}"),
];

const int maxTurns = 25;

for (var turn = 0; turn < maxTurns; turn++)
{
    var response = await client.GetResponseAsync(messages, chatOptions);

    // Append all response messages to history
    foreach (var msg in response.Messages)
        messages.Add(msg);

    // Print any assistant text
    foreach (var msg in response.Messages.Where(m => m.Role == ChatRole.Assistant))
    {
        var text = msg.Text;
        if (!string.IsNullOrWhiteSpace(text))
        {
            Console.WriteLine(text);
        }

        // Log tool calls for visibility
        foreach (var item in msg.Contents.OfType<FunctionCallContent>())
        {
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"  🔧 {item.Name}({Summarize(item.Arguments)})");
            Console.ResetColor();
        }
    }

    // If the model didn't invoke any tools this turn, it's done
    bool anyToolCalls = response.Messages
        .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

    if (!anyToolCalls)
        break;
}

Console.WriteLine("\n✅ Research complete.");

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptUser(string prompt)
{
    Console.Write(prompt);
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "recent advances in renewable energy"
        : input;
}

static string Summarize(IDictionary<string, object?>? args)
{
    if (args is null || args.Count == 0) return "";
    return string.Join(", ", args.Select(kv =>
    {
        var val = kv.Value?.ToString() ?? "";
        return val.Length > 80 ? $"{kv.Key}: \"{val[..77]}...\"" : $"{kv.Key}: \"{val}\"";
    }));
}

// ===================================================================
// Web Search Tool – uses DuckDuckGo HTML search (no API key needed)
// ===================================================================
sealed class WebSearchTool
{
    private static readonly HttpClient Http = CreateHttpClient();

    private static HttpClient CreateHttpClient()
    {
        var handler = new HttpClientHandler
        {
            AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate,
        };
        var http = new HttpClient(handler) { Timeout = TimeSpan.FromSeconds(15) };
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
        return http;
    }

    [Description("Search the web for a query and return a list of result titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query")] string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseDuckDuckGoResults(html);

            if (results.Count == 0)
                return "No results found.";

            var sb = new StringBuilder();
            foreach (var r in results.Take(8))
                sb.AppendLine($"- **{r.Title}**\n  {r.Snippet}\n  URL: {r.Url}\n");

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch the text content of a web page URL for deeper reading. Returns plain text.")]
    public async Task<string> FetchPageAsync(
        [Description("The URL to fetch")] string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            // Limit to ~4000 chars to stay within context limits
            return text.Length > 4000 ? text[..4000] + "\n\n[... truncated ...]" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseDuckDuckGoResults(string html)
    {
        var results = new List<SearchResult>();
        // Match result blocks: <a class="result__a" ...>title</a> and <a class="result__snippet" ...>snippet</a>
        var linkPattern = new Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
            RegexOptions.Singleline | RegexOptions.IgnoreCase);
        var snippetPattern = new Regex(
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline | RegexOptions.IgnoreCase);

        var links = linkPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        for (var i = 0; i < links.Count; i++)
        {
            var rawUrl = links[i].Groups[1].Value;
            var title = StripTags(links[i].Groups[2].Value);

            // DuckDuckGo wraps URLs in a redirect; extract the actual URL
            var actualUrl = ExtractUrl(rawUrl);
            var snippet = i < snippets.Count ? StripTags(snippets[i].Groups[1].Value) : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(title.Trim(), snippet.Trim(), actualUrl));
        }
        return results;
    }

    private static string ExtractUrl(string ddgUrl)
    {
        // DuckDuckGo uses //duckduckgo.com/l/?uddg=<encoded_url>&...
        var match = Regex.Match(ddgUrl, @"uddg=([^&]+)");
        return match.Success ? Uri.UnescapeDataString(match.Groups[1].Value) : ddgUrl;
    }

    private static string StripTags(string html)
        => Regex.Replace(html, @"<[^>]+>", "").Trim();

    private static string StripHtml(string html)
    {
        // Remove script/style blocks, then tags, then collapse whitespace
        var cleaned = Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", " ",
            RegexOptions.Singleline | RegexOptions.IgnoreCase);
        cleaned = Regex.Replace(cleaned, @"<[^>]+>", " ");
        cleaned = WebUtility.HtmlDecode(cleaned);
        cleaned = Regex.Replace(cleaned, @"\s+", " ");
        return cleaned.Trim();
    }

    private record SearchResult(string Title, string Snippet, string Url);
}

