sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save an important finding, fact, or quote to the notebook for later reference.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        return $"Saved note #{_notes.Count}.";
    }

    [Description("Retrieve all saved notes from the notebook.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "Notebook is empty.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }
}

